//! Source-derived Spike guard rules generated by scripts/extract_spike_guards.py.

use std::{collections::HashMap, sync::OnceLock};

use serde_json::Value;

struct SourceRules {
    whole_alignments: HashMap<String, u8>,
    distinct_bases: HashMap<String, (usize, usize)>,
    lmul_alignments: HashMap<String, Vec<LmulAlignment>>,
    config_guards: HashMap<String, Vec<Value>>,
}

#[derive(Clone, Copy)]
struct LmulAlignment {
    rank: usize,
    scale_num: u16,
    scale_den: u16,
}

fn source_rules() -> &'static SourceRules {
    static RULES: OnceLock<SourceRules> = OnceLock::new();
    RULES.get_or_init(|| {
        let archive: Value =
            serde_json::from_str(include_str!("../../../data/spike_guard_rules.json"))
                .expect("bundled Spike guard archive must be valid JSON");
        let mut result = SourceRules {
            whole_alignments: HashMap::new(),
            distinct_bases: HashMap::new(),
            lmul_alignments: HashMap::new(),
            config_guards: HashMap::new(),
        };
        if let Some(instructions) = archive["instructions"].as_object() {
            for (mnemonic, guards) in instructions {
                let Some(guards) = guards.as_array() else {
                    continue;
                };
                for guard in guards {
                    if guard["unconditional_context"] != true {
                        continue;
                    }
                    if guard["guard"] == "require"
                        && guard["category"] == "C_config"
                        && let Some(expression) = guard["normalized_ast"]
                            .as_array()
                            .and_then(|values| values.first())
                    {
                        result
                            .config_guards
                            .entry(mnemonic.clone())
                            .or_default()
                            .push(expression.clone());
                    }
                    match guard["rule"]["kind"].as_str() {
                        Some("group_alignment") => {
                            if guard["rule"]["vector_rank"].as_u64().is_some()
                                && let Some(width) = guard["rule"]["group_size"]
                                    .as_u64()
                                    .and_then(|n| u8::try_from(n).ok())
                            {
                                result.whole_alignments.insert(mnemonic.clone(), width);
                            }
                        }
                        Some("register_base_inequality") => {
                            if let (Some(left), Some(right)) = (
                                guard["rule"]["left_vector_rank"]
                                    .as_u64()
                                    .and_then(|n| usize::try_from(n).ok()),
                                guard["rule"]["right_vector_rank"]
                                    .as_u64()
                                    .and_then(|n| usize::try_from(n).ok()),
                            ) {
                                result
                                    .distinct_bases
                                    .insert(mnemonic.clone(), (left, right));
                            }
                        }
                        Some("lmul_alignment") => {
                            let rank = guard["rule"]["vector_rank"]
                                .as_u64()
                                .and_then(|n| usize::try_from(n).ok());
                            if let (Some(rank), Some(scale_num), Some(scale_den)) = (
                                rank,
                                guard["rule"]["scale_num"]
                                    .as_u64()
                                    .and_then(|n| u16::try_from(n).ok()),
                                guard["rule"]["scale_den"]
                                    .as_u64()
                                    .and_then(|n| u16::try_from(n).ok()),
                            ) && scale_den > 0
                            {
                                result
                                    .lmul_alignments
                                    .entry(mnemonic.clone())
                                    .or_default()
                                    .push(LmulAlignment {
                                        rank,
                                        scale_num,
                                        scale_den,
                                    });
                            }
                        }
                        _ => {}
                    }
                }
            }
        }
        result
    })
}

pub(crate) fn whole_register_alignment(mnemonic: &str) -> Option<u8> {
    source_rules().whole_alignments.get(mnemonic).copied()
}

pub(crate) fn distinct_base_ranks(mnemonic: &str) -> Option<(usize, usize)> {
    source_rules().distinct_bases.get(mnemonic).copied()
}

pub(crate) fn required_lmul_alignment(mnemonic: &str, rank: usize, lmul: &str) -> Option<u8> {
    let (lmul_num, lmul_den) = crate::rvv_legal::lmul_ratio(lmul)?;
    source_rules()
        .lmul_alignments
        .get(mnemonic)?
        .iter()
        .filter(|rule| rule.rank == rank)
        .filter_map(|rule| {
            let numerator = u32::from(lmul_num) * u32::from(rule.scale_num);
            let denominator = u32::from(lmul_den) * u32::from(rule.scale_den);
            (denominator > 0)
                .then(|| numerator.div_ceil(denominator).max(1))
                .and_then(|width| u8::try_from(width).ok())
        })
        .max()
}

fn evaluate_config_ast(node: &Value, sew: u16, lmul: f64, elen: u16) -> Option<f64> {
    fn truth(value: bool) -> f64 {
        if value { 1.0 } else { 0.0 }
    }
    match node["node"].as_str()? {
        "number" => node["value"].as_str()?.parse().ok(),
        "name" => match node["value"].as_str()? {
            "e8" => Some(8.0),
            "e16" => Some(16.0),
            "e32" => Some(32.0),
            "e64" => Some(64.0),
            "true" => Some(1.0),
            "false" => Some(0.0),
            _ => None,
        },
        "role" => match node["value"].as_str()? {
            "SEW" => Some(f64::from(sew)),
            "LMUL" => Some(lmul),
            "ELEN" => Some(f64::from(elen)),
            _ => None,
        },
        "unary" => {
            let value = evaluate_config_ast(&node["arg"], sew, lmul, elen)?;
            match node["op"].as_str()? {
                "-" => Some(-value),
                "!" => Some(truth(value == 0.0)),
                _ => None,
            }
        }
        "binary" => {
            let left = evaluate_config_ast(&node["left"], sew, lmul, elen)?;
            let right = evaluate_config_ast(&node["right"], sew, lmul, elen)?;
            match node["op"].as_str()? {
                "+" => Some(left + right),
                "-" => Some(left - right),
                "*" => Some(left * right),
                "/" if right != 0.0 => Some(left / right),
                "%" if right != 0.0 => Some(left % right),
                "<" => Some(truth(left < right)),
                "<=" => Some(truth(left <= right)),
                ">" => Some(truth(left > right)),
                ">=" => Some(truth(left >= right)),
                "==" => Some(truth(left == right)),
                "!=" => Some(truth(left != right)),
                "&&" => Some(truth(left != 0.0 && right != 0.0)),
                "||" => Some(truth(left != 0.0 || right != 0.0)),
                _ => None,
            }
        }
        _ => None,
    }
}

pub(crate) fn config_allows(mnemonic: &str, sew: u16, lmul: &str, elen: u16) -> bool {
    let Some((num, den)) = crate::rvv_legal::lmul_ratio(lmul) else {
        return false;
    };
    let ratio = f64::from(num) / f64::from(den);
    source_rules()
        .config_guards
        .get(mnemonic)
        .is_none_or(|guards| {
            guards.iter().all(|guard| {
                evaluate_config_ast(guard, sew, ratio, elen).is_none_or(|value| value != 0.0)
            })
        })
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn whole_register_shapes_come_from_spike_guard_ast() {
        assert_eq!(whole_register_alignment("vl4re32.v"), Some(4));
        assert_eq!(whole_register_alignment("vs4r.v"), Some(4));
        assert_eq!(whole_register_alignment("vadd.vv"), None);
        assert_eq!(distinct_base_ranks("vcompress.vm"), Some((0, 1)));
        assert_eq!(required_lmul_alignment("vrgather.vv", 2, "m4"), Some(4));
        assert_eq!(required_lmul_alignment("vfwadd.vv", 0, "m2"), Some(4));
        assert_eq!(required_lmul_alignment("vsext.vf4", 1, "m4"), Some(1));
        assert!(config_allows("vfwadd.vv", 32, "m4", 64));
        assert!(!config_allows("vfwadd.vv", 64, "m4", 64));
        assert!(!config_allows("vfwadd.vv", 32, "m8", 64));
        assert!(!config_allows("vqdot.vv", 64, "m1", 64));
        assert!(crate::rvv_legal::opcode_config_eligible(
            "vqdot.vv", 32, "m1", 64
        ));
        assert!(!crate::rvv_legal::opcode_config_eligible(
            "vqdot.vv", 64, "m1", 64
        ));
    }
}
